        string id=actor.Get("id").AsString();var displayed=Map(owner,"display_states");if(!displayed.ContainsKey(id))return;var before=_settings.authored(actor);var after=before.Duplicate(true);var state=snapshot(new Settings{[id]=displayed[id]})[id].AsGodotDictionary();double time=owner.Get("requested_time").AsDouble();var frozen=new Settings{["state"]=state,["time"]=time};after["frozen"]=frozen;after["mode"]=3;state["v"]=Vector3.Zero;state["w"]=Vector3.Zero;state["responds"]=false;state["velocities"]=new Vector3[state["velocities"].AsVector3Array().Length];if(state.ContainsKey("fog_velocity"))state["fog_velocity"]=new Vector3[state["fog_velocity"].AsVector3Array().Length];if(before["type"].AsInt32()==8){var shapes=new Settings();var source=_growth.points(owner,id,time);var transform=_growth.world(owner,id,time);var growth=_growth.data(actor);var geometry=new SurfaceGrowthGeometry();var controls=Get(Get(Map(owner,"prototypes")[id].AsGodotDictionary(),"growth",new Settings()).AsGodotDictionary(),"controls",new GArray()).AsGodotArray();var points=state["points"].AsVector3Array();foreach(var value in controls){var control=value.AsGodotDictionary();var inverse=(transform*geometry.point_frame(growth!,control["root"].AsGodotDictionary(),source)).AffineInverse();int count=control["count"].AsInt32(),first=control["first"].AsInt32();var result=new Vector3[count];for(int i=0;i<count;i++)result[i]=inverse*points[first+i];shapes[control["id"]]=result;}frozen["growth_shapes"]=shapes;}foreach(var value in state["bones"].AsGodotDictionary().Values){var bone=value.AsGodotDictionary();bone["v"]=Vector3.Zero;bone["root_v"]=Vector3.Zero;}var history=model.Get("history").As<UndoRedo>();var action=new PhysicsSettingsHistoryAction(model,actor,before,after);history.CreateAction("Freeze Physics");history.AddDoMethod(new Callable(action,nameof(PhysicsSettingsHistoryAction.restore_after)));history.AddUndoMethod(new Callable(action,nameof(PhysicsSettingsHistoryAction.restore_before)));histor